rules.parameterizedBody:
{{#if anomalous}}
	    Rule "{{{ruleName}}}" triggered at {{dateTimeFormat timestamp format="full"}}.
    {{else}}
	    Rule "{{{ruleName}}}" cleared at {{dateTimeFormat timestamp format="full"}}.
    {{/if}}
    {{#if anomalous}}
      Triggering condition: {{{readableRule}}}
    {{/if}}
    {{#if anomalous}}
      Signal value: {{inputs.A.value}}
    {{else}}
      Current signal value: {{inputs.A.value}}
    {{/if}}
    {{#notEmpty dimensions}}
      Signal details: {{{dimensions}}}
    {{/notEmpty}}
    {{#if anomalous}}
      {{#if runbookUrl}}
        Runbook: {{{runbookUrl}}}
      {{/if}}
      {{#if tip}}
        Tip: {{{tip}}}
      {{/if}}
    {{/if}}
